import{Mt as e,dt as t,n,pt as r}from"./chunks/framework.CaLsa5bj.js";var i=JSON.parse(`{"title":"版本与发布","description":"","frontmatter":{},"headers":[],"relativePath":"guide/release.md","filePath":"guide/release.md","lastUpdated":1794389503000}`),a={name:`guide/release.md`};function o(n,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[r(`<h1 id="版本与发布" tabindex="-1">版本与发布 <a class="header-anchor" href="#版本与发布" aria-label="Permalink to “版本与发布”">​</a></h1><p><code>@bubblesjs/workflow-vue-core</code> 是公开的 npm 包，首发版本为 <code>0.1.0</code>，已设置 <code>publishConfig.access: &quot;public&quot;</code>。根项目、<code>docs</code> 和 <code>vue-playground</code> 保持 <code>private: true</code>，不参与 npm 发布。组件包构建 ESM、CJS、类型声明和 CSS，供工作区应用和外部项目引用。</p><p><code>pnpm verify:packages</code> 验证本地产物，并将 tarball 安装到独立项目，在最低支持的 Vue 版本下分别检查 ESM、CJS 声明。独立项目使用 <code>strict: true</code>、<code>skipLibCheck: false</code> 和 <code>types: []</code>，确保声明所需的类型随包提供，不依赖工作区的类型自动加载；该检查已包含在 <code>pnpm ready</code> 中。</p><p>Changesets 和发布工作流负责公开包的版本与发布。CI、发布和文档部署统一使用 Node.js <code>26.13.0</code> 与 pnpm <code>12.15.0</code>。</p><h2 id="发布前核对" tabindex="-1">发布前核对 <a class="header-anchor" href="#发布前核对" aria-label="Permalink to “发布前核对”">​</a></h2><p>首次发布前完成以下配置：</p><ol><li>核对目标包的包名与版本，确保没有 <code>private: true</code>，且 <code>publishConfig.access</code> 为 <code>public</code>；当前包名为 <code>@bubblesjs/workflow-vue-core</code>，首发版本为 <code>0.1.0</code>。</li><li>完善 <code>repository</code>、<code>homepage</code>、<code>bugs</code>、作者和许可证信息。</li><li>核对 <code>files</code>、<code>exports</code>、ESM/CJS 与类型入口，以及 <code>style.css</code> 导出。</li><li>保持 Vue 为 peer dependency，并验证包的使用方能加载组件及样式。</li><li>核对 <code>.changeset/config.json</code> 的默认分支与仓库实际分支一致，确认发布账户拥有目标 scope 的权限。</li></ol><p>包名变更时，同步更新 <code>workspace:*</code> 依赖、源码导入、开发别名、TypeScript 映射和产物验证脚本。配置完成后运行 <code>pnpm install</code> 和 <code>pnpm ready</code>。</p><h2 id="记录与发布版本" tabindex="-1">记录与发布版本 <a class="header-anchor" href="#记录与发布版本" aria-label="Permalink to “记录与发布版本”">​</a></h2><p>修改公开包后记录变更：</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> changeset</span></span></code></pre></div><p>选择受影响的包，填写版本级别和变更说明。私有应用不参与 npm 发布。</p><p>准备版本时运行：</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version-packages</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ready</span></span></code></pre></div><p>检查生成的版本、变更日志和锁文件后，在有发布权限的环境执行 <code>pnpm release</code>。该命令会发布符合条件的新版本。</p><p>首发 <code>0.1.0</code> 已在包清单中确定，可以直接在检查通过后运行 <code>pnpm release</code>；后续变更再通过 Changesets 升级版本。</p><p><code>.github/workflows/release.yml</code> 在合入或推送到 <code>main</code> 的 CI 全部通过后自动运行，也支持通过 <code>workflow_dispatch</code> 在 <code>main</code> 手动触发。自动触发时会核对 CI 检查的提交仍然是 <code>main</code> 的最新提交，跳过过时的 CI 结果。工作流先执行 <code>pnpm ready</code>；存在待处理的 Changeset 时创建或更新版本 PR，版本 PR 合入 <code>main</code> 且 CI 通过后自动发布尚未发布的包版本。升版脚本会更新版本、变更日志和锁文件，并执行格式化。</p><p>在仓库设置中允许 GitHub Actions 创建版本 PR，并配置具有 <code>@bubblesjs</code> scope 发布权限的 <code>NPM_TOKEN</code>。未配置该令牌时，工作流只创建或更新版本 PR。</p><h2 id="部署文档与-playground" tabindex="-1">部署文档与 Playground <a class="header-anchor" href="#部署文档与-playground" aria-label="Permalink to “部署文档与 Playground”">​</a></h2><p>文档产物位于 <code>apps/docs/.vitepress/dist/</code>：</p><div class="language-bash" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:preview</span></span></code></pre></div><p>默认部署路径是 <code>/</code>。通过 <code>DOCS_BASE</code> 指定子路径，例如在 PowerShell 中：</p><div class="language-powershell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DOCS_BASE </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/workflow/&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pnpm docs:build</span></span></code></pre></div><p>Playground 产物位于 <code>apps/playgroud/vue/dist/</code>。独立部署时默认路径为 <code>/</code>，通过 <code>PLAYGROUND_BASE</code> 指定子路径：</p><div class="language-powershell" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PLAYGROUND_BASE </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/workflow/playground/&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pnpm build:vue</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pnpm preview</span></span></code></pre></div><p>使用 GitHub Pages 时，将构建来源设为 <strong>GitHub Actions</strong>。Release 工作流通过 Changesets 实际发布 npm 新版本后，会自动调用 <code>.github/workflows/docs.yml</code>（<strong>Deploy docs and playground</strong>），部署本次 npm 发布对应提交的文档与 Playground。仅创建或更新版本 PR、没有新版本可发布、未配置 <code>NPM_TOKEN</code>，或 npm 发布失败时，不会自动部署。也可手动运行文档工作流独立部署。</p><p>工作流根据仓库名设置 <code>DOCS_BASE</code>，将 Vue 的 <code>PLAYGROUND_BASE</code> 设为文档路径下的 <code>playground/</code>，将 React 的 <code>PLAYGROUND_REACT_BASE</code> 设为 <code>playground/react/</code>。依次构建文档、组件库和两个 Playground 后，将 Playground 产物合并到文档产物的对应目录，一起部署到同一个 Pages 站点。</p><p>合并后的静态产物会通过 <code>GITHUB_TOKEN</code> 推送到 <code>gh-pages</code> 分支，首次部署时自动创建分支，后续部署更新分支内容并保留提交历史。文档工作流及 Release 中调用它的 <code>docs</code> 作业均需要 <code>contents: write</code> 权限。站点仍通过 Pages artifact 部署，仓库 Pages 构建来源保持 <strong>GitHub Actions</strong>，无需额外配置发布令牌。</p><p>当前仓库部署后的访问地址：</p><ul><li><a href="https://bubblesplant.github.io/workflow/" target="_blank" rel="noreferrer">文档站点</a></li><li><a href="https://bubblesplant.github.io/workflow/playground/" target="_blank" rel="noreferrer">在线 Playground</a></li><li><a href="https://github.com/bubblesplant/workflow" target="_blank" rel="noreferrer">GitHub 仓库</a></li></ul><p>文档导航、首页和交互示例页都提供 Playground 入口。用户或组织主页仓库使用根路径 <code>/</code>，对应的 Playground 路径为 <code>/playground/</code>；使用自定义域名时，按实际访问路径调整两个应用的 base。</p>`,31)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};